#include <stdio.h>
#include <limits.h>
int main(void) {
    int f = 50;
    double c = (f - 32) * (5 / 9);
    printf("%.2f\n", c);
    return 0;
}

#include <stdio.h>
#include <limits.h>
int main(void) {
    int f = 50;
    double c = (f - 32) * (5.0 / 9.0);
    printf("%.2f\n", c);
    return 0;
}

