#include <stdio.h>
#include <limits.h>
int main(void) {
    int unit_cents = 199;
    int count = 3;
    int total_cents = unit_cents * count;
    printf("%d.%02d\n", total_cents / 100, total_cents % 100);
    return 0;
}

